'use strict';
/**
 * The demo brand's Videos: five short clips (four tall 9:16 and one wide 16:9) made on this computer with ffmpeg-static from
 * three scenes composed from the real demo photos in the posts' style (D125, postComposer.renderFrame): a hook, three steps and an end card, each with a slow zoom, joined with 0.5 second
 * cross-fades, 11 seconds long, with a silent audio track so every player treats them as normal clips. Nothing is
 * generated by a model and nothing is charged. Each clip has a poster picture of the same name (used by the Library tile).
 * Each StudioVideo row is written in the stored shape of models/StudioVideo.js (a finished one-clip video).
 */
const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');
const mongoose = require('mongoose');
const { PRODUCTS, BRAND } = require('./constants');
const { assetUrl } = require('./safety');
const images = require('./images');
const designs = require('./postDesigns');
const composer = require('./postComposer');
const realPhotos = require('./realPhotos');
const { QUARK_COSTS } = require('../../config/apiCosts');

const DAY = 86400000;
const SCENE_SECONDS = 4;
const FADE = 0.5;
const SECONDS = SCENE_SECONDS * 3 - FADE * 2; // 11

/** The five videos (product slug, title, the owner's idea, the card lines) and how long ago each was made. */
const VIDEOS = Object.freeze([
  { slug: 'kumkumadi-glow-serum', title: 'Kumkumadi Glow Serum: the 30 second night ritual', hook: 'Your 30 second night ritual', ritual: 'Three drops, every night', lines: ['Saffron and manjistha', 'Light, never greasy', 'Fragrance-light'],
    idea: 'A calm night ritual with the Kumkumadi Glow Serum, three drops on clean skin.', daysAgo: 118, wide: false },
  { slug: 'coconut-hibiscus-hair-oil', title: 'Sunday oil bath, made easy', hook: 'The Sunday oil bath, made easy', ritual: 'Warm, massage, rest', lines: ['Cold-pressed coconut oil', 'Hibiscus and curry leaf', 'Soft, shiny hair'],
    idea: 'The Sunday oil bath our grandmothers did, in three easy steps with the Coconut and Hibiscus Hair Oil.', daysAgo: 84, wide: false },
  { slug: 'rose-petal-toner', title: 'A midday refresh in one spritz', hook: 'A midday refresh in one spritz', ritual: 'Mist, breathe, carry on', lines: ['Steam-distilled rose water', 'Alcohol-free', 'Fine mist'],
    idea: 'A quick midday refresh with the Rose Petal Toner for hot Chennai afternoons.', daysAgo: 49, wide: false },
  { slug: 'lip-balm-trio', title: 'Diwali gifting: the Lip Balm Trio', hook: 'A small gift people actually use', ritual: 'Bare, Rose, Beet', lines: ['Kokum butter and beeswax', 'Three tinted shades', 'Pocket-sized gift'],
    idea: 'A festive gifting teaser for the Lip Balm Trio, warm and simple.', daysAgo: 20, wide: false },
  { slug: 'saffron-sandal-face-mask', title: 'Saffron and Sandal Face Mask: a Sunday glow', hook: 'A Sunday glow in ten minutes', ritual: 'Mix, apply, rest, rinse', lines: ['Saffron and sandalwood', 'Gentle clay', 'Twice a week'],
    idea: 'A wide video for our website, showing the Saffron and Sandal Face Mask ritual.', daysAgo: 5, wide: true }
]);

/**
 * One tall clip per reel post (D125), used ONLY by that reel in the Library (no Videos page row; flat file names
 * `videos/reel-<post key>.mp4`, because the Library finds the poster of a demo video only in that folder and shows the poster
 * as the tile): so no two reels share a tile, and no reel plays the wide studio video (a wide clip is cropped in a tile).
 * The first scene is the post's own headline on its own photo; the second the steps; the third the end card.
 */
function reelSpecs() {
  const all = require('./content').allSpecs();
  return [...all.any, ...all.past, ...all.soon].filter((s) => s.fmt === 'reel').map((s) => {
    const cover = designs.designFor(s).cover;
    const words = designs.reelLinesFor(s);
    const first = cover.photoSlot ? { photoSlot: cover.photoSlot, crop: cover.crop } : cover.photos[0];
    const second = cover.photos && cover.photos[1] ? cover.photos[1] : first;
    return Object.freeze({ slug: s.key, product: s.product, hook: s.head, kicker: cover.kicker || 'Reel', ritual: words.head, stepsKicker: words.kicker, lines: words.lines,
      mood: cover.mood, first, second, variant: cover.family === 'collage' ? 'collage' : (cover.variant || 'band'), prints: cover.photos || [], wide: false, reel: true });
  });
}
const REELS = Object.freeze(reelSpecs());

const mp4Rel = (v) => `videos/${v.reel ? 'reel-' : ''}${v.slug}.mp4`;
const posterRel = (v) => `videos/${v.reel ? 'reel-' : ''}${v.slug}.jpg`;
const productSlugOf = (v) => v.product || v.slug;

/** The frame specs of a video's three scenes (pure): a studio video uses its product's how-to and ritual photos. */
function framesOf(v) {
  const slug = productSlugOf(v);
  const P = designs.P[slug] || {};
  const first = v.first || { photoSlot: P.howto.photoSlot, crop: P.howto.crop };
  const second = v.second || (P.ritual.photoSlot ? { photoSlot: P.ritual.photoSlot, crop: P.ritual.crop } : first);
  const mood = v.mood || P.howto.mood || 'plum';
  const base = { wide: Boolean(v.wide), product: slug };
  return [
    { ...base, kind: 'hook', mood, ...first, variant: v.variant || (v.wide ? 'bottom' : 'band'), prints: v.prints || [], kicker: v.kicker || 'New on Zaya', head: v.hook },
    { ...base, kind: 'steps', mood: mood === 'ivory' ? 'blush' : mood, ...second, kicker: v.stepsKicker || 'In three steps', head: v.ritual, lines: v.lines },
    { ...base, kind: 'end', mood, ...first, head: BRAND.tagline }
  ];
}

/** The three scenes of a video, composed from the real photos (a drawn packshot stands in where a photo is missing). */
function scenesOf(v, photo = realPhotos.photoSource()) {
  const fallback = (f) => images.packshotJpg(PRODUCTS.find((p) => p.slug === f.product) || PRODUCTS[0], 1, 960);
  return framesOf(v).map((f) => composer.renderFrame(f, { photo, fallback }).buffer);
}

/** The ffmpeg arguments for one clip from three scene files. Pure (tested). */
function ffmpegArgs({ scenes, out, wide }) {
  const [w, h] = wide ? [1280, 720] : [720, 1280];
  const frames = SCENE_SECONDS * 30;
  const zoom = scenes.map((_, i) => `[${i}:v]scale=${w * 2}:${h * 2},setsar=1,zoompan=z='min(zoom+0.0007,1.12)':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=${frames}:s=${w}x${h}:fps=30,format=yuv420p[v${i}]`);
  const o1 = SCENE_SECONDS - FADE; const o2 = o1 + SCENE_SECONDS - FADE;
  const graph = [...zoom, `[v0][v1]xfade=transition=fade:duration=${FADE}:offset=${o1}[x1]`, `[x1][v2]xfade=transition=fade:duration=${FADE}:offset=${o2}[v]`].join(';');
  return [
    '-y', '-hide_banner', '-loglevel', 'error',
    ...scenes.flatMap((s) => ['-i', s]),
    '-f', 'lavfi', '-i', 'anullsrc=channel_layout=stereo:sample_rate=44100',
    '-filter_complex', graph, '-map', '[v]', '-map', `${scenes.length}:a`,
    '-c:v', 'libx264', '-preset', 'veryfast', '-crf', '24', '-pix_fmt', 'yuv420p', '-movflags', '+faststart', '-c:a', 'aac', '-b:a', '48k', '-t', String(SECONDS), out
  ];
}

function ffmpegPath() {
  try { const p = require('ffmpeg-static'); return p && fs.existsSync(p) ? p : null; } catch (_) { return null; }
}

/**
 * Makes the poster and the clip of one video under `demoDir` (skipped when both are already there). Returns
 * { made: number of files made, skipped: reason or '' }. When ffmpeg is missing the poster is still made and the
 * video is reported as skipped, so the caller can say so.
 */
function makeVideo({ demoDir, video, run = spawnSync, ffmpeg = ffmpegPath(), photo }) {
  const poster = path.join(demoDir, posterRel(video)); const clip = path.join(demoDir, mp4Rel(video));
  fs.mkdirSync(path.dirname(poster), { recursive: true });
  const scenes = photo ? scenesOf(video, photo) : scenesOf(video);
  let made = 0;
  // the poster is the first scene; when it changed (a new design or a new photo) the clip is made again too (deterministic,
  // so an unchanged video is never remade)
  const same = fs.existsSync(poster) && fs.readFileSync(poster).equals(scenes[0]);
  if (!same) { fs.writeFileSync(poster, scenes[0]); made += 1; fs.rmSync(clip, { force: true }); }
  if (fs.existsSync(clip)) return { made, skipped: '' };
  if (!ffmpeg) return { made, skipped: 'ffmpeg is not available' };
  const work = fs.mkdtempSync(path.join(path.dirname(clip), '.work-'));
  try {
    const files = scenes.map((buf, i) => { const f = path.join(work, `scene${i}.jpg`); fs.writeFileSync(f, buf); return f; });
    const tmp = path.join(work, 'out.mp4');
    const r = run(ffmpeg, ffmpegArgs({ scenes: files, out: tmp, wide: video.wide }), { timeout: 180000, encoding: 'utf8' });
    if (r.status !== 0 || !fs.existsSync(tmp)) return { made, skipped: `ffmpeg failed (${String(r.stderr || r.error || '').slice(0, 160)})` };
    fs.renameSync(tmp, clip);
    return { made: made + 1, skipped: '' };
  } finally {
    fs.rmSync(work, { recursive: true, force: true });
  }
}

/**
 * The video link of each product, for its reels in the Library: { product slug: url } (a tall studio video, else the product's
 * first reel clip). The seed lays reelUrlsOf over it, so each reel plays its own clip.
 */
function videoUrlsOf(base) {
  const out = {};
  for (const v of VIDEOS.filter((x) => !x.wide)) out[v.slug] = assetUrl(base, mp4Rel(v));
  for (const r of REELS) if (!out[r.product]) out[r.product] = assetUrl(base, mp4Rel(r));
  return out;
}

/** The clip of every reel post: { post key: url }. */
const reelUrlsOf = (base) => Object.fromEntries(REELS.map((r) => [r.slug, assetUrl(base, mp4Rel(r))]));

/** The StudioVideo rows. `hasFile(video)` says whether the clip file exists (a video without a file is not written). */
function build({ userId, now, base, hasFile = () => true }) {
  const rows = [];
  for (const v of VIDEOS) {
    if (!hasFile(v)) continue;
    const createdAt = new Date(now.getTime() - v.daysAgo * DAY + 11 * 3600000);
    rows.push({
      _id: new mongoose.Types.ObjectId(), user: userId, status: 'completed', title: v.title, idea: v.idea, concept: v.idea, spokenLine: '', style: 'natural', language: 'english', voice: 'female',
      aspectRatio: v.wide ? '16:9' : '9:16', clips: 1, clipsDone: 1, parts: [], transition: 'fade', subtitles: false, logo: true, endLine: BRAND.tagline, platforms: ['instagram', 'youtube'],
      notice: '', prompt: '', references: [], parent: null, change: '', videoUrl: assetUrl(base, mp4Rel(v)), seconds: SECONDS, quarks: QUARK_COSTS.studio_video, refunded: false,
      payer: userId, error: '', clipUrls: [], startedAt: createdAt, completedAt: new Date(createdAt.getTime() + 4 * 60000), createdAt, updatedAt: new Date(createdAt.getTime() + 4 * 60000)
    });
  }
  return rows;
}

module.exports = { VIDEOS, REELS, SECONDS, mp4Rel, posterRel, framesOf, scenesOf, ffmpegArgs, ffmpegPath, makeVideo, videoUrlsOf, reelUrlsOf, build };
